#include <algorithm>
#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <random>
#include <vector>

// Same additions, same data, two orders of visiting it.
[[nodiscard]] double time_ms(const std::vector<std::int32_t>& data, const std::vector<std::int32_t>& order,
                             std::int64_t& sink) {
  const auto start = std::chrono::steady_clock::now();
  std::int64_t total = 0;
  for (std::ptrdiff_t i = 0; i < std::ssize(order); ++i) total += data[order[i]];
  sink += total;
  return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

int main() {
  constexpr std::ptrdiff_t kCount = 8'000'000;  // 32 MB of data, and a 32 MB index to walk it with
  std::vector<std::int32_t> data(kCount, 1);
  std::vector<std::int32_t> in_order(kCount);
  std::iota(in_order.begin(), in_order.end(), 0);
  std::vector<std::int32_t> shuffled = in_order;
  std::mt19937 generator(12345);  // a fixed seed, so the two runs see the same permutation
  std::ranges::shuffle(shuffled, generator);

  std::int64_t sink = 0;
  for (int round = 0; round < 3; ++round) {
    const double sequential = time_ms(data, in_order, sink);
    const double random = time_ms(data, shuffled, sink);
    std::cout << std::format("round {}: in order {:.1f} ms, shuffled {:.1f} ms, ratio {:.1f}\n", round, sequential,
                             random, random / sequential);
  }
  std::cout << std::format("sink {}\n", sink);
}

#include <cstdint>
#include <cstdlib>
#include <format>
#include <iostream>
#include <new>
#include <string>
#include <string_view>
#include <vector>

std::int64_t allocations = 0;  // global only because a replacement operator new has to be global

void* operator new(std::size_t size) {
  ++allocations;
  if (void* p = std::malloc(size)) return p;
  throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

// Returns a new string every call. The text is 25 characters, past the 15 a std::string holds inside itself.
[[nodiscard]] std::string describe_by_value(float range) {
  if (range < 1.0F) return std::string("obstacle within one metre");
  if (range < 5.0F) return std::string("clear for the next metres");
  return std::string("nothing within five metres");
}

// Returns a view of a string literal, which lives for the whole program.
[[nodiscard]] std::string_view describe_by_view(float range) {
  if (range < 1.0F) return "obstacle within one metre";
  if (range < 5.0F) return "clear for the next metres";
  return "nothing within five metres";
}

int main() {
  constexpr std::ptrdiff_t kBeams = 3600;
  std::vector<float> ranges(kBeams);
  for (std::ptrdiff_t i = 0; i < kBeams; ++i) ranges[i] = 0.2F + static_cast<float>((i * 37) % 900) / 100.0F;

  std::int64_t near_by_value = 0;
  const std::int64_t before_value = allocations;
  for (const float range : ranges) {
    if (describe_by_value(range).starts_with("obstacle")) ++near_by_value;
  }
  const std::int64_t value_allocations = allocations - before_value;

  std::int64_t near_by_view = 0;
  const std::int64_t before_view = allocations;
  for (const float range : ranges) {
    if (describe_by_view(range).starts_with("obstacle")) ++near_by_view;
  }
  const std::int64_t view_allocations = allocations - before_view;

  std::cout << std::format("{} beams, {} near either way: {}\n", kBeams, near_by_value,
                           near_by_value == near_by_view);
  std::cout << std::format("returning std::string: {} allocations\n", value_allocations);
  std::cout << std::format("returning std::string_view: {} allocations\n", view_allocations);
}

for (const float range : ranges) {
  const std::string label = label_by_value(range);  // one std::string per beam
  if (label.starts_with("obstacle")) ++counts.near_beams;
  else if (label.starts_with("clear")) ++counts.mid_beams;
  else ++counts.far_beams;
}

#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <format>
#include <iostream>
#include <new>
#include <string>
#include <string_view>
#include <vector>

std::int64_t allocations = 0;  // global only because a replacement operator new has to be global

void* operator new(std::size_t size) {
  ++allocations;
  if (void* p = std::malloc(size)) return p;
  throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct Counts {
  std::int64_t near_beams = 0;
  std::int64_t mid_beams = 0;
  std::int64_t far_beams = 0;

  [[nodiscard]] bool operator==(const Counts&) const = default;
};

// Before: a fresh std::string for every beam, 25 characters, past the 15 a string holds inside itself.
[[nodiscard]] std::string label_by_value(float range) {
  if (range < 1.0F) return std::string("obstacle within one metre");
  if (range < 5.0F) return std::string("clear for the next metres");
  return std::string("nothing within five metres");
}

[[nodiscard]] Counts classify_slow(const std::vector<float>& ranges, std::ptrdiff_t scans) {
  Counts counts;
  for (std::ptrdiff_t scan = 0; scan < scans; ++scan) {
    for (const float range : ranges) {
      const std::string label = label_by_value(range);
      if (label.starts_with("obstacle")) ++counts.near_beams;
      else if (label.starts_with("clear")) ++counts.mid_beams;
      else ++counts.far_beams;
    }
  }
  return counts;
}

// After: the same three answers as an enumeration, with no storage to own.
enum class Band { near_obstacle, clear_ahead, nothing_near };

[[nodiscard]] Band band_of(float range) {
  if (range < 1.0F) return Band::near_obstacle;
  if (range < 5.0F) return Band::clear_ahead;
  return Band::nothing_near;
}

[[nodiscard]] Counts classify_fast(const std::vector<float>& ranges, std::ptrdiff_t scans) {
  Counts counts;
  for (std::ptrdiff_t scan = 0; scan < scans; ++scan) {
    for (const float range : ranges) {
      switch (band_of(range)) {
        case Band::near_obstacle: ++counts.near_beams; break;
        case Band::clear_ahead: ++counts.mid_beams; break;
        case Band::nothing_near: ++counts.far_beams; break;
      }
    }
  }
  return counts;
}

int main() {
  constexpr std::ptrdiff_t kBeams = 3600;
  constexpr std::ptrdiff_t kScans = 200;
  std::vector<float> ranges(kBeams);
  for (std::ptrdiff_t i = 0; i < kBeams; ++i) ranges[i] = 0.2F + static_cast<float>((i * 37) % 900) / 100.0F;

  const std::int64_t before_slow = allocations;
  const auto slow_start = std::chrono::steady_clock::now();
  const Counts slow = classify_slow(ranges, kScans);
  const double slow_ms =
      std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - slow_start).count();
  const std::int64_t slow_allocations = allocations - before_slow;

  const std::int64_t before_fast = allocations;
  const auto fast_start = std::chrono::steady_clock::now();
  const Counts fast = classify_fast(ranges, kScans);
  const double fast_ms =
      std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - fast_start).count();
  const std::int64_t fast_allocations = allocations - before_fast;

  // The times go to standard error: they differ per machine and per run, so they are not part of the result.
  std::cerr << std::format("slow {:.1f} ms, fast {:.1f} ms, ratio {:.1f}\n", slow_ms, fast_ms, slow_ms / fast_ms);
  std::cout << std::format("{} beams x {} scans\n", kBeams, kScans);
  std::cout << std::format("same answer both ways: {}, near {}, mid {}, far {}\n", slow == fast, fast.near_beams,
                           fast.mid_beams, fast.far_beams);
  std::cout << std::format("allocations before the fix: {}\n", slow_allocations);
  std::cout << std::format("allocations after the fix: {}\n", fast_allocations);
}

#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>

constexpr std::int64_t kSteps = 100'000'000;

// The result goes nowhere, so at -O2 there is nothing here to time.
[[gnu::noinline]] double time_unused() {
  const auto start = std::chrono::steady_clock::now();
  std::int64_t total = 0;
  for (std::int64_t k = 0; k < kSteps; ++k) total += k % 7;
  return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

// The same loop, with its result handed to the caller, so the work has to happen.
[[gnu::noinline]] double time_used(std::int64_t& sink) {
  const auto start = std::chrono::steady_clock::now();
  std::int64_t total = 0;
  for (std::int64_t k = 0; k < kSteps; ++k) total += k % 7;
  sink += total;
  return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

int main() {
  std::int64_t sink = 0;
  std::cout << std::format("result unused: {:.1f} ms for {} steps\n", time_unused(), kSteps);
  const double used = time_used(sink);
  std::cout << std::format("result used:   {:.1f} ms for {} steps, sink {}\n", used, kSteps, sink);
}
